function handle_npc_intractions () {
    for (let value of spriteutils.getSpritesWithin(SpriteKind.npc, 30, mySprite)) {
        if (sprites.readDataNumber(value, "NPCID") == 2) {
            value.sayText("V", 100, false)
            if (browserEvents.V.isPressed()) {
                value.sayText("")
                MakeNPCText("Its been getting really dangerous outside the city")
                MakeNPCText("I'm here to keep watch and stand gard")
                MakeNPCText("This is one of the last towns left so we must protect it")
                MakeNPCText("You better come in and stay safe young one")
            }
        }
    }
}
browserEvents.C.onEvent(browserEvents.KeyEvent.Pressed, function () {
    if (!(lockcontrols && (incutesence && mainstartmenu))) {
        if (!(inattack)) {
            platformer.moveSprite(mySprite, false, 90)
            inattack = true
            if (theAbutton == 0) {
                if (duraction_facing_left_or_right == 1) {
                    sprites.setDataNumber(attack_hitbox, "damge", -1)
                    if (sword_compo >= 1) {
                        sword_compo = 0
                        animation.runImageAnimation(
                        attack_hitbox,
                        melleattackslist[1],
                        50,
                        false
                        )
                    } else {
                        sword_compo = 1
                        animation.runImageAnimation(
                        attack_hitbox,
                        melleattackslist[0],
                        50,
                        false
                        )
                    }
                } else {
                    if (sword_compo >= 1) {
                        sword_compo = 0
                        animation.runImageAnimation(
                        attack_hitbox,
                        attacksflipped[1],
                        50,
                        false
                        )
                    } else {
                        sword_compo = 1
                        animation.runImageAnimation(
                        attack_hitbox,
                        attacksflipped[0],
                        50,
                        false
                        )
                    }
                }
                timer.background(function () {
                    for (let index = 0; index < attacksflipped[0].length - 3; index++) {
                        pause(50)
                    }
                    inattack = false
                    platformer.moveSprite(mySprite, true, 90)
                })
            } else if (theAbutton == 1) {
                sprites.setDataNumber(attack_hitbox, "damge", -1.5)
                if (duraction_facing_left_or_right == 1) {
                    if (sword_compo >= 1) {
                        sword_compo = 0
                        animation.runImageAnimation(
                        attack_hitbox,
                        melleattackslist[2],
                        50,
                        false
                        )
                    } else {
                        sword_compo = 1
                        animation.runImageAnimation(
                        attack_hitbox,
                        melleattackslist[3],
                        50,
                        false
                        )
                    }
                } else {
                    if (sword_compo >= 1) {
                        sword_compo = 0
                        animation.runImageAnimation(
                        attack_hitbox,
                        attacksflipped[2],
                        50,
                        false
                        )
                    } else {
                        sword_compo = 1
                        animation.runImageAnimation(
                        attack_hitbox,
                        attacksflipped[3],
                        50,
                        false
                        )
                    }
                }
                timer.background(function () {
                    for (let index = 0; index < attacksflipped[2].length - 2; index++) {
                        pause(50)
                    }
                    inattack = false
                    platformer.moveSprite(mySprite, true, 90)
                })
            }
        }
    }
})
